import { NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { db } from '@/lib/db'
import { isAdmin } from '@/lib/auth/session'
import { logger } from '@/lib/logger'
import { setAuthenticatedDatabaseContext } from '@/lib/auth/requestContext'

// AUTO-GENERATED by api-row-sweep --apply — column types from migrations/*.sql + name heuristics.
// pg returns bigint/numeric as string, timestamptz as Date; nullable columns carry `| null`; REVIEW.
interface ProjectRow {
  count: string
}

export const dynamic = 'force-dynamic'

/**
 * GET /api/subscription/project-count
 *
 * Returns the user's project count for subscription limit checks.
 * Admins get a count of all projects (since they can see everything).
 */
export async function GET() {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ count: 0 }, { status: 401 })
    }

    const userId = session.user.id
    const userIsAdmin = await isAdmin()
    setAuthenticatedDatabaseContext(userId)

    let count: number
    if (userIsAdmin) {
      const { rows } = await db.query<ProjectRow>('SELECT COUNT(*) as count FROM projects')
      count = parseInt(rows[0]?.count || '0', 10)
    } else {
      const { rows } = await db.query<ProjectRow>('SELECT COUNT(*) as count FROM projects WHERE user_id = $1', [userId])
      count = parseInt(rows[0]?.count || '0', 10)
    }

    return NextResponse.json({ count })
  } catch (error) {
    logger.error('[/api/subscription/project-count] Error:', { error: error })
    return NextResponse.json({ count: 0 }, { status: 500 })
  }
}
